const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const ROWS = [
  { id: 'b', tenant: 't1', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 't2', createdAt: '2026-01-01', total: 9 },
  { id: 'a', tenant: 't1', createdAt: '2026-01-01', total: 1 },
  { id: 'c', tenant: 't1', createdAt: '2026-01-03', total: 3 },
  { id: 'ab', tenant: 't1', createdAt: '2026-01-01', total: 4 }, // equal date, id 'a' < 'ab'
  { id: 'aa', tenant: 't1', createdAt: '2026-01-01', total: 5 },
  { id: '1', tenant: 't1', createdAt: '2026-01-03', total: 6 }   // lexicographic: '1' < 'c'
];

function fresh(rows) { return new OrderHandler(new OrderRepository(rows || ROWS)); }

// 1. ordering + tenant filter + limit without cursor (input array not mutated)
const input = [...ROWS];
const h = fresh();
assert.deepEqual(h.list({ tenant: 't1', limit: 100 }).items.map(o => o.id), ['a', 'aa', 'ab', 'b', '1', 'c']);
assert.deepEqual(h.list({ tenant: 't2', limit: 10 }).items.map(o => o.id), ['x']);
assert.deepEqual(h.list({ tenant: 'none', limit: 1 }), { items: [], nextCursor: null });
assert.deepEqual(input, ROWS, 'input array must not be mutated');

// 2. pagination sweep: page 3 at a time, no repeats or skips
const all = ROWS.filter(r => r.tenant === 't1').sort((p, q) => p.createdAt < q.createdAt ? -1 : p.createdAt > q.createdAt ? 1 : p.id < q.id ? -1 : p.id > q.id ? 1 : 0);
const seen = [];
let cursor;
let pages = 0;
let h2 = fresh();
do {
  const page = h2.list({ tenant: 't1', limit: 3, cursor });
  assert.deepEqual(page.items.map(o => o.id), all.slice(seen.length, seen.length + 3).map(o => o.id));
  seen.push(...page.items.map(o => o.id));
  assert.equal(page.items.length, Math.min(3, all.length - seen.length + 3));
  cursor = page.nextCursor;
  if (cursor) assert.equal(page.nextCursor, page.items[page.items.length - 1].createdAt + '|' + page.items[page.items.length - 1].id);
  pages++;
} while (cursor);
assert.equal(pages, 2);
assert.deepEqual(seen, ['a', 'aa', 'ab', 'b', '1', 'c']);

// 3. nextCursor null exactly when nothing further matches
const one = fresh().list({ tenant: 't1', limit: 6 });
assert.equal(one.nextCursor, null);
const mid = fresh().list({ tenant: 't1', limit: 5 });
assert.equal(mid.nextCursor, '2026-01-03|1');
const fullTwo = fresh().list({ tenant: 't1', limit: 2 });
assert.equal(fullTwo.nextCursor, '2026-01-01|aa');

// 4. resume strictly after pair even if cursor row has been deleted
const missingRow = ROWS.filter(r => !(r.id === 'b' && r.tenant === 't1'));
const p = fresh(missingRow).list({ tenant: 't1', limit: 100, cursor: '2026-01-02|b' });
assert.deepEqual(p.items.map(o => o.id), ['1', 'c']);

// 5. cursor pair from another tenant still resumes correctly for this tenant
const otherTenant = fresh(ROWS).list({ tenant: 't1', limit: 100, cursor: '2026-01-01|x' });
// rows with createdAt 2026-01-01 and ids a/aa/ab sort strictly BEFORE pair (2026-01-01, x)
assert.deepEqual(otherTenant.items.map(o => o.id), ['b', '1', 'c']);
const otherTenantLater = fresh(ROWS).list({ tenant: 't1', limit: 100, cursor: '2026-01-02|zzz' });
assert.deepEqual(otherTenantLater.items.map(o => o.id), ['1', 'c']);

// 6. equal-date orders never repeat or skip across pages
const dupRows = [
  { id: 'A', tenant: 't', createdAt: 'd', total: 1 },
  { id: 'B', tenant: 't', createdAt: 'd', total: 2 },
  { id: 'C', tenant: 't', createdAt: 'd', total: 3 },
  { id: 'D', tenant: 't', createdAt: 'd', total: 4 }
];
const seen2 = [];
let cursor2 = undefined;
for (;;) {
  const page = fresh(dupRows).list({ tenant: 't', limit: 1, cursor: cursor2 });
  seen2.push(...page.items.map(o => o.id));
  cursor2 = page.nextCursor;
  if (!cursor2) break;
  const consumed = page.items[page.items.length - 1];
  assert.equal(cursor2, consumed.createdAt + '|' + consumed.id);
}
assert.deepEqual(seen2, ['A', 'B', 'C', 'D']);

// 7. invalid requests
for (const bad of [
  { tenant: '', limit: 1 },
  { tenant: 't1', limit: 0 },
  { tenant: 't1', limit: 101 },
  { tenant: 't1', limit: 1.5 },
  { tenant: 't1', limit: Infinity },
  { tenant: 't1', limit: 1, cursor: 'no-separator' },
  { tenant: 't1', limit: 1, cursor: 'only|' },
  { tenant: 't1', limit: 1, cursor: '|only' },
  { tenant: 't1', limit: 1, cursor: 'a|b|c' },
  { tenant: 't1', limit: 1, cursor: '|' },
  { tenant: 't1', limit: 1, cursor: '' }
]) {
  assert.throws(() => fresh().list(bad), err => err instanceof Error && err.message === 'invalid request');
}
// boundaries are valid
assert.doesNotThrow(() => fresh().list({ tenant: 't1', limit: 1 }));
assert.doesNotThrow(() => fresh().list({ tenant: 't1', limit: 100, cursor: '2026-01-01|a' }));

// 8. rows themselves not mutated
assert.deepEqual(ROWS.map(r => ({ ...r })), ROWS.map(r => ({ ...r })));
const snapshot = JSON.stringify(ROWS);
fresh().list({ tenant: 't1', limit: 3 });
assert.equal(JSON.stringify(ROWS), snapshot, 'repository rows must not be mutated');

console.log('all extended checks passed');

