import { Order, Page } from './types';

const SEPARATOR = '|';

export interface CursorPair {
  createdAt: string;
  id: string;
}

/**
 * Parses `createdAt|id` into its pair. `undefined` means "no cursor" and yields null.
 * Anything else must split on '|' into exactly two nonempty parts (ids and dates never
 * contain '|'), otherwise this throws the shared invalid-request error.
 */
export function parseCursor(cursor?: string): CursorPair | null {
  if (cursor === undefined) return null;
  const parts = typeof cursor === 'string' ? cursor.split(SEPARATOR) : [];
  if (parts.length !== 2 || !parts[0] || !parts[1]) throw new Error('invalid request');
  return { createdAt: parts[0], id: parts[1] };
}

/** Ascending lexicographic order by createdAt, then id. */
function compareOrders(a: Order, b: Order): number {
  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

/** True when row's (createdAt, id) pair sorts strictly after the cursor pair. */
function isAfterCursor(row: Order, cursor: CursorPair): boolean {
  if (row.createdAt !== cursor.createdAt) return row.createdAt > cursor.createdAt;
  return row.id > cursor.id;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  /** All rows of one tenant, ascending by createdAt then id. Input array is never mutated. */
  list(tenant: string): Order[] {
    return this.sorted(tenant);
  }

  /**
   * Cursor page for one tenant: rows are filtered by tenant first, sorted ascending by
   * (createdAt, id), and resumed strictly after the cursor pair when one is supplied.
   * The resume point is a key comparison, not a row lookup, so it still works when the
   * cursor row has been deleted or belonged to another tenant.
   */
  page(tenant: string, limit: number, cursor?: string): Page {
    if (!tenant || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new Error('invalid request');
    }
    const cursorPair = parseCursor(cursor);
    const sorted = this.sorted(tenant);
    const start = cursorPair ? firstAfter(sorted, cursorPair) : 0;
    const end = Math.min(start + limit, sorted.length);
    const items = sorted.slice(start, end);
    const last = items[items.length - 1];
    const nextCursor = end < sorted.length && last ? last.createdAt + SEPARATOR + last.id : null;
    return { items, nextCursor };
  }

  /** Tenant filter applied before pagination; filters into a new array so sorting never mutates the input. */
  private sorted(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort(compareOrders);
  }
}

function firstAfter(sorted: Order[], cursorPair: CursorPair): number {
  let index = 0;
  while (index < sorted.length && !isAfterCursor(sorted[index], cursorPair)) index++;
  return index;
}
